# -*- coding: utf-8 -*-
"""
Звуковые ассеты для строя: Укулеле
Количество нот: 4
"""

import base64
from typing import Optional
import tempfile
import os

try:
    from kivy.core.audio import SoundLoader
    from kivy.clock import Clock
    KIVY_AVAILABLE = True
except ImportError:
    KIVY_AVAILABLE = False

# G4 -> G4.ogg
_G4_BASE64 = """"""

# C4 -> C4.ogg
_C4_BASE64 = """"""

# E4 -> E4.ogg
_E4_BASE64 = """"""

# A4 -> A4.ogg
_A4_BASE64 = """"""

NOTES_METADATA = {
    "G4": {
        "filename": "G4.ogg",
        "size": 20405,
        "duration": 2.500,
        "sample_rate": 44100,
        "channels": 1,
        "compressed": True,
    },

    "C4": {
        "filename": "C4.ogg",
        "size": 19109,
        "duration": 2.500,
        "sample_rate": 44100,
        "channels": 1,
        "compressed": True,
    },

    "E4": {
        "filename": "E4.ogg",
        "size": 20342,
        "duration": 2.500,
        "sample_rate": 44100,
        "channels": 1,
        "compressed": True,
    },

    "A4": {
        "filename": "A4.ogg",
        "size": 20366,
        "duration": 2.500,
        "sample_rate": 44100,
        "channels": 1,
        "compressed": True,
    },

}

_HAS_SOUNDFILE = True

class UkuleleSounds:
    """Звуки для строя: Укулеле"""

    _NOTE_NAME_MAP = {
        "G4": "G4",
        "C4": "C4",
        "E4": "E4",
        "A4": "A4",
    }

    @staticmethod
    def get_sound_data(note_name: str) -> Optional[bytes]:
        safe_name = UkuleleSounds._NOTE_NAME_MAP.get(note_name)
        if safe_name:
            var_name = f"_{safe_name}_BASE64"
            if var_name in globals():
                return base64.b64decode(globals()[var_name])
        return None

    @staticmethod
    def get_sound(note_name: str):
        if not KIVY_AVAILABLE:
            return None
        data = UkuleleSounds.get_sound_data(note_name)
        if data:
            try:
                ext = ".ogg" if _HAS_SOUNDFILE else ".wav"
                fd, path = tempfile.mkstemp(suffix=ext)
                os.close(fd)
                with open(path, "wb") as f:
                    f.write(data)
                sound = SoundLoader.load(path)
                def _cleanup(dt):
                    try:
                        if os.path.exists(path):
                            os.unlink(path)
                    except Exception:
                        pass
                Clock.schedule_once(_cleanup, 5.0)
                return sound
            except Exception:
                return None
        return None

    @staticmethod
    def get_all_notes() -> list:
        return list(NOTES_METADATA.keys())

TUNING_NAME = "Укулеле"
TUNING_ID = "ukulele"
__all__ = ["UkuleleSounds", "NOTES_METADATA"]